#include "ksStatePackRefreshTask.h"
#include <iostream>
#include <stdexcept>
using T=ks::StatePackRefreshTask;void check(bool b,const char* w){if(!b)throw std::runtime_error(w);}
int main(){try{uint64_t cases=0;for(bool all:{false,true})for(unsigned group=0;group<256;++group)for(unsigned value=0;value<256;++value){T task(all?T::Entry::All:T::Entry::One,group);unsigned reads=0,writes=0,children=0,clocks=0;const unsigned storeClocks=value&3;auto read=[&](T::Read r)->unsigned{++reads;if(r==T::Read::Base)return 0xffa30000;check(task.descriptorOffset()==uint8_t(uint8_t(task.group()-1)<<2),"Descriptor byte wrap differs");return task.group()%6;};auto write=[&](uint32_t field,uint8_t byte){check(field==0x1000+children&&byte==uint8_t(value+children),"Packed write differs");++writes;};while(!task.complete()){if(task.awaitingRecipe()){++children;check(task.recipe()==ks::StatePackFieldsTask::Kind(task.group()%6),"Typed recipe differs");check(task.resumeRecipe(uint8_t(value+children),0x1000+children),"Recipe rejected");continue;}const auto c=task.nextClocks(storeClocks),before=reads,stores=writes;check(!task.advanceBefore(c-1,read,write,storeClocks)&&reads==before&&writes==stores,"Packing refresh early read/write");check(task.advanceBefore(c,read,write,storeClocks)==c,"Pack refresh admission differs");clocks+=c;}const unsigned expected=all?3+6*(15+105+3+3+storeClocks+3+3+3)+17:105; // internal call and six post-store loop boundaries
if(clocks!=expected){std::cerr<<"all="<<all<<" clocks="<<clocks<<" expected="<<expected<<'\n';throw std::runtime_error("Refresh clock schedule differs");}check(children==(all?6:1)&&reads==2*children&&writes==(all?6:0)&&!task.resumeRecipe(0,0),"Refresh lifetime/order differs");++cases;}std::cout<<"PASS: "<<cases<<" full indexed/all6recipe jobs,byte descriptor indexing wrap,typed child values/fields,store cost/deadlines/order/clocks\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
